 private static boolean matches(NodeUpdateCodec.Message report,NodeReleaseManifest release){return report.imageSha.equals(release.imageSha)&&report.artifact.equals(release.id)&&Arrays.equals(report.descriptor,release.body)&&report.version.equals(release.version)&&report.buildId.equals(release.buildId)&&report.commit.equals(release.commit)&&report.ref.equals(release.ref);}
 private JSONObject marker(Operation o,boolean activated)throws Exception{return new JSONObject().put("schema","aumanet.node-update-operation.v1").put("operationId",o.id).put("groupId",o.saved.group).put("selfId",o.saved.self).put("epoch",o.saved.epoch).put("nodeId",o.nodeId).put("originalRun",o.originalRun).put("beforeSha256",o.beforeSha).put("releaseDigest",o.release.manifest.id).put("imageSha256",o.release.manifest.imageSha).put("nodePin",find(o.config.config,o.nodeId).publicKeySha256.toLowerCase(Locale.ROOT)).put("configDigest",o.config.digest).put("configRevision",o.config.revision).put("activated",activated);}
 private boolean compatible(NodeUpdateCodec.Message report,Operation operation,GatewayBindingConfig.Node node){return (operation.release.manifest.role!=3||report.imageRole==3)&&report.role==(node.id.equals(operation.field.base)?1:2)&&(report.flags&9)==9&&report.capacity==NodeReleaseManifest.MAX_IMAGE&&report.bootState!=2;}
 private NodeUpdateTransport operationTransport(Operation o,GatewayBindingConfig.Node node,GroupIdentity identity){return new NodeUpdateTransport(node,o.saved.group,o.saved.epoch,o.field.owner,o.field.relay,()->socket(o.activated?recoveryNetwork(o):o.group.network,o.field.scope.address,o.field.config.localGateway()),new NodeUpdateTransport.Signer(){public boolean permitted(NodeUpdateCodec.Message message){return message.kind=='C'&&message.action==1?preboot(o)&&issuer.radioCurrent(o.field):o.activated?postboot(o):preboot(o);}public byte[] sign(NodeUpdateCodec.Message message)throws Exception{if(!permitted(message)||!message.target.equals(o.nodeId)||message.kind=='S'&&(!message.artifact.equals(o.release.manifest.id)||!message.run.equals(o.originalRun))||message.kind=='C'&&(message.action==1&&!message.run.equals(o.originalRun)||!message.artifact.equals(o.release.manifest.id)))throw new SecurityException();byte[] signature=identity.signGatewayUpdate(message,o.saved.group,o.saved.epoch,o.nodeId,o.field.relay);if(!permitted(message))throw new SecurityException();return signature;}},SystemClock::elapsedRealtime,()->o.activated?postboot(o):preboot(o));}
