 private NodeUpdateTransport readTransport(GatewayLeaseIssuer.RadioContext field,GatewayBindingConfig.Node node,BooleanSupplier live){return new NodeUpdateTransport(node,field.scope.group,field.scope.epoch,field.owner,field.relay,()->socket((Network)field.scope.network,field.scope.address,field.config.localGateway()),message->{if(!live.getAsBoolean()||message.kind!='Q')throw new SecurityException();byte[] signed=group.internetIdentity(group.internetScope()).signGatewayUpdate(message,field.scope.group,field.scope.epoch,node.id,field.relay);if(!live.getAsBoolean())throw new SecurityException();return signed;},SystemClock::elapsedRealtime,live);}
 private static DatagramSocket socket(Network network,String address,String gateway)throws Exception{if(network==null)throw new IOException();DatagramSocket socket=new DatagramSocket(null);try{network.bindSocket(socket);socket.bind(new InetSocketAddress(InetAddress.getByName(address),0));socket.connect(InetAddress.getByName(gateway),NodeUpdateCodec.PORT);return socket;}catch(Exception failed){socket.close();throw failed;}}
