 private void observe(NodeUpdateCodec.Message report,GatewayConfigStore.Record record){if(report.role!=(report.target.equals(record.config.radioRelayNode())?1:2))throw new SecurityException();observations.put(report.target,new Observation(report,SystemClock.elapsedRealtime(),record));sequence.incrementAndGet();}
 private void reconcile(NodeUpdateCodec.Message report)throws Exception{JSONObject marker=journal.current();if(marker==null||!marker.getString("nodeId").equals(report.target))return;GatewayConfigStore.Record checked=config();if(checked.revision!=marker.getLong("configRevision")||!checked.digest.equals(marker.getString("configDigest"))||!find(checked.config,report.target).publicKeySha256.equalsIgnoreCase(marker.getString("nodePin")))return;TrustedConnectionScope s=group.trustedConnectionScope();if(s==null||!marker.getString("groupId").equals(s.group)||!marker.getString("selfId").equals(s.self)||marker.getLong("epoch")!=s.epoch)return;if(report.imageSha.equals(marker.getString("imageSha256"))&&NodeReleaseManifest.hash(report.descriptor).equals(marker.getString("releaseDigest"))&&report.bootState==1&&(report.state==0||report.state==5)){journal.clear();resolved(marker,"complete");error="";}else if(report.imageSha.equals(marker.getString("beforeSha256"))&&report.bootState!=2&&(!marker.getBoolean("activated")&&(report.state==0||report.state==5||report.state==6)||!report.run.equals(marker.getString("originalRun")))){journal.clear();resolved(marker,marker.getBoolean("activated")?"rolled-back":"failed");error="";}}
